// Before: collection scan
// db.jobs.find({ status: "open", "location.city": "Berlin" })

// Create the index once:
db.jobs.createIndex({ status: 1, "location.city": 1 });

// Now the query can use it:
db.jobs.find({ status: "open", "location.city": "Berlin" });

// List the indexes on the collection:
db.jobs.getIndexes();
// -> [ { _id: 1 }, { status: 1, "location.city": 1 } ]

// Query: status = "open", sort by createdAt desc, salaryMin > 60000
db.jobs.createIndex({ status: 1, createdAt: -1, salaryMin: 1 });

// Prefixes this index can serve:
//   { status: "open" }                         yes
//   { status: "open" } sort createdAt -1       yes
//   { createdAt: -1 } only                     no (not a prefix)

const result = db.jobs.find({ status: "open", salaryMin: { $gt: 60000 } })
  .sort({ createdAt: -1 })
  .limit(20)
  .explain("executionStats");

db.jobs.find({ status: "open" }).sort({ createdAt: -1 })
  .explain("executionStats");

// Look for:
// "stage": "IXSCAN"            -> index used
// "stage": "COLLSCAN"          -> full scan, add an index
// "stage": "SORT" (blocking)   -> in-memory sort
// executionStats.executionStages:
//   nReturned, totalKeysExamined, totalDocsExamined

// Verify which index was selected:
db.jobs.find({ status: "open" }).hint({ status: 1, createdAt: -1 }).explain();

// Embedded: job owns its skills, read and written together
{ _id: ObjectId("..."), title: "Backend Engineer",
