// Referenced: company is shared by many jobs
// job: { title: "QA Engineer", companyId: ObjectId("...") }
// -> one company document updated once, referenced everywhere

const job = await jobs.findOne({ _id: jobId });
const company = await companies.findOne({ _id: job.companyId });

const byTag = await jobs.aggregate([
  { $match: { status: "open" } },
  { $unwind: "$tags" },
  { $sort: { createdAt: -1 } },
  { $limit: 20 },
  { $project: { title: 1, tags: 1, salaryMin: 1 } }
]).toArray();

// One document with 3 tags becomes three documents,
// each carrying one tag, limited to 20 rows total.

const report = await jobs.aggregate([
  { $match: { status: "open" } },
  { $group: {
      _id: "$location.city",
      total: { $sum: 1 },
      avgSalary: { $avg: "$salaryMin" }
  } },
  { $sort: { total: -1 } },
  { $lookup: {
      from: "companies",
      localField: "_id",
      foreignField: "city",
      as: "companies"
  } }
]).toArray();

